//! Differential ratchet for
//! `src/engine/battleScriptSetalwayshitflagOpcode.ts`. Expected projected
//! results and exact errors are generated by invoking the canonical TypeScript
//! opcode handler; regenerate with `node --experimental-strip-types
//! core-rs/tools/gen-battle-script-setalwayshitflag-vectors.mjs`.

use std::collections::BTreeSet;

use factory_core::battle_script_setalwayshitflag::{
    apply_battle_script_setalwayshitflag, BattleScriptSetalwayshitflagBattlerState,
    BattleScriptSetalwayshitflagRoles, BattleScriptSetalwayshitflagRules,
    BATTLE_SCRIPT_SETALWAYSHITFLAG_BATTLERS, BATTLE_SCRIPT_SETALWAYSHITFLAG_BATTLER_COUNT,
    BATTLE_SCRIPT_STATUS3_ALWAYS_HITS, BATTLE_SCRIPT_STATUS3_ALWAYS_HITS_TURN_2,
};
use factory_core::battle_script_setalwayshitflag_vectors_gen::{
    BattleScriptSetalwayshitflagVectorCase, BattleScriptSetalwayshitflagVectorState,
    BATTLE_SCRIPT_SETALWAYSHITFLAG_BATTLER_DOMAIN, BATTLE_SCRIPT_SETALWAYSHITFLAG_BRANCH_CENSUS,
    BATTLE_SCRIPT_SETALWAYSHITFLAG_CASES, BATTLE_SCRIPT_SETALWAYSHITFLAG_CATEGORY_CENSUS,
    BATTLE_SCRIPT_SETALWAYSHITFLAG_COUNTER_DOMAIN, BATTLE_SCRIPT_SETALWAYSHITFLAG_DOMAIN_CENSUS,
    BATTLE_SCRIPT_SETALWAYSHITFLAG_PAIR_DOMAIN, BATTLE_SCRIPT_SETALWAYSHITFLAG_STATUS3_EDGE_DOMAIN,
    BATTLE_SCRIPT_SETALWAYSHITFLAG_VECTOR_CORPUS_SHA256,
};

fn rules(value: BattleScriptSetalwayshitflagVectorState) -> BattleScriptSetalwayshitflagRules {
    BattleScriptSetalwayshitflagRules {
        battlers: core::array::from_fn(|index| BattleScriptSetalwayshitflagBattlerState {
            status3: value.status3[index],
            battler_with_sure_hit: value.battler_with_sure_hit[index],
        }),
        selector_roles: BattleScriptSetalwayshitflagRoles {
            attacker: value.attacker,
            target: value.target,
        },
    }
}

fn vector_state(
    value: BattleScriptSetalwayshitflagRules,
) -> BattleScriptSetalwayshitflagVectorState {
    BattleScriptSetalwayshitflagVectorState {
        status3: value.battlers.map(|battler| battler.status3),
        battler_with_sure_hit: value.battlers.map(|battler| battler.battler_with_sure_hit),
        attacker: value.selector_roles.attacker,
        target: value.selector_roles.target,
    }
}

#[test]
fn complete_projected_outputs_and_typed_role_errors_match_canonical_typescript() {
    assert_eq!(BATTLE_SCRIPT_SETALWAYSHITFLAG_CASES.len(), 71);
    for (case_index, case) in BATTLE_SCRIPT_SETALWAYSHITFLAG_CASES.iter().enumerate() {
        execute_case(case_index, case);
    }
}

fn execute_case(case_index: usize, case: &BattleScriptSetalwayshitflagVectorCase) {
    let input = rules(case.initial);
    let before = input;
    match (
        apply_battle_script_setalwayshitflag(&input),
        case.expected,
        case.expected_error,
    ) {
        (Ok(actual), Some(expected), None) => {
            let target = before.selector_roles.target.unwrap_or_else(|| {
                panic!("case {case_index} {}: success vector has no target", case.label)
            });
            let attacker = before.selector_roles.attacker.unwrap_or_else(|| {
                panic!("case {case_index} {}: success vector has no attacker", case.label)
            });
            let target_index = target.index();

            assert_eq!(
                input, before,
                "case {case_index} {}: native transformation mutated input",
                case.label,
            );
            assert_eq!(
                vector_state(actual),
                expected,
                "case {case_index} {}: complete projected output",
                case.label,
            );
            assert_eq!(
                actual.selector_roles, before.selector_roles,
                "case {case_index} {}: changed selector roles",
                case.label,
            );
            for battler in BATTLE_SCRIPT_SETALWAYSHITFLAG_BATTLERS {
                if battler != target {
                    assert_eq!(
                        actual.battlers[battler.index()],
                        before.battlers[battler.index()],
                        "case {case_index} {}: changed non-target battler {}",
                        case.label,
                        battler.as_u8(),
                    );
                }
            }
            assert_eq!(
                actual.battlers[target_index].status3 & !BATTLE_SCRIPT_STATUS3_ALWAYS_HITS,
                before.battlers[target_index].status3 & !BATTLE_SCRIPT_STATUS3_ALWAYS_HITS,
                "case {case_index} {}: changed target status3 outside STATUS3_ALWAYS_HITS",
                case.label,
            );
            assert_eq!(
                actual.battlers[target_index].status3 & BATTLE_SCRIPT_STATUS3_ALWAYS_HITS,
                BATTLE_SCRIPT_STATUS3_ALWAYS_HITS_TURN_2,
                "case {case_index} {}: did not replace target always-hits counter with turn 2",
                case.label,
            );
            assert_eq!(
                actual.battlers[target_index].battler_with_sure_hit,
                attacker,
                "case {case_index} {}: did not store attacker as target sure-hit owner",
                case.label,
            );
        }
        (Err(error), None, Some(expected_error)) => {
            assert_eq!(
                input, before,
                "case {case_index} {}: failed transformation mutated input",
                case.label,
            );
            assert_eq!(
                error.to_string(),
                expected_error,
                "case {case_index} {}: exact typed-reachable role error",
                case.label,
            );
        }
        (result, expected, expected_error) => panic!(
            "case {case_index} {}: generated outcome shape disagrees with native result: result={result:?}, expected={expected:?}, expected_error={expected_error:?}",
            case.label,
        ),
    }
}

#[test]
fn matrix_covers_all_pairs_packed_inputs_prior_owners_and_self_targets() {
    let matrix = BATTLE_SCRIPT_SETALWAYSHITFLAG_CASES
        .iter()
        .filter(|case| case.category == "attacker-target-counter-matrix")
        .collect::<Vec<_>>();
    assert_eq!(matrix.len(), 64);

    let pairs = matrix
        .iter()
        .map(|case| {
            let attacker = case
                .initial
                .attacker
                .unwrap_or_else(|| panic!("matrix case {} is missing attacker", case.label));
            let target = case
                .initial
                .target
                .unwrap_or_else(|| panic!("matrix case {} is missing target", case.label));
            (attacker.as_u8(), target.as_u8())
        })
        .collect::<BTreeSet<_>>();
    assert_eq!(
        pairs.into_iter().collect::<Vec<_>>(),
        BATTLE_SCRIPT_SETALWAYSHITFLAG_PAIR_DOMAIN,
        "every canonical attacker/target pair, including self-targets, must remain represented",
    );

    let mut counters = [0_usize; 4];
    let mut prior_owners = [0_usize; 4];
    let mut self_target_cases = 0;
    for case in matrix {
        let target = case
            .initial
            .target
            .unwrap_or_else(|| panic!("matrix case {} is missing target", case.label));
        let target_index = target.index();
        let counter = ((case.initial.status3[target_index] & BATTLE_SCRIPT_STATUS3_ALWAYS_HITS)
            >> 3) as usize;
        counters[counter] += 1;
        prior_owners[case.initial.battler_with_sure_hit[target_index].as_u8() as usize] += 1;
        if case.initial.attacker == case.initial.target {
            self_target_cases += 1;
        }
    }
    assert_eq!(
        counters,
        [16, 16, 16, 16],
        "every incoming packed counter 0..3 must occur for every pair",
    );
    assert_eq!(
        prior_owners,
        [16, 16, 16, 16],
        "every prior battlerWithSureHit value must be overwritten across the matrix",
    );
    assert_eq!(
        self_target_cases, 16,
        "each of the four self-target pairs must retain all four packed-counter inputs",
    );
}

#[test]
fn fixed_four_slot_domain_u32_edges_and_source_constants_are_retained() {
    assert_eq!(BATTLE_SCRIPT_SETALWAYSHITFLAG_BATTLER_COUNT, 4);
    assert_eq!(
        BATTLE_SCRIPT_SETALWAYSHITFLAG_BATTLERS.map(|battler| battler.as_u8()),
        BATTLE_SCRIPT_SETALWAYSHITFLAG_BATTLER_DOMAIN,
    );
    assert_eq!(BATTLE_SCRIPT_SETALWAYSHITFLAG_BATTLER_DOMAIN, [0, 1, 2, 3]);
    assert_eq!(BATTLE_SCRIPT_SETALWAYSHITFLAG_COUNTER_DOMAIN, [0, 1, 2, 3]);
    assert_eq!(
        BATTLE_SCRIPT_SETALWAYSHITFLAG_STATUS3_EDGE_DOMAIN,
        [0x0000_0000, u32::MAX, 0x8000_0010, 0xffff_ffe7],
    );
    assert_eq!(BATTLE_SCRIPT_STATUS3_ALWAYS_HITS, 0x0000_0018);
    assert_eq!(BATTLE_SCRIPT_STATUS3_ALWAYS_HITS_TURN_2, 0x0000_0010);
}

#[test]
fn domain_category_branch_censuses_and_corpus_hash_are_ratchet_pinned() {
    assert_eq!(
        BATTLE_SCRIPT_SETALWAYSHITFLAG_DOMAIN_CENSUS,
        [
            ("battler-slots", 4),
            ("attacker-role-values", 4),
            ("target-role-values", 4),
            ("attacker-target-pairs", 16),
            ("status3-u32-values", 4_294_967_296),
            ("always-hits-packed-counter-inputs", 4),
            ("prior-sure-hit-owner-values", 4),
            ("typed-missing-role-combinations", 3),
        ],
    );
    assert_eq!(
        BATTLE_SCRIPT_SETALWAYSHITFLAG_CATEGORY_CENSUS,
        [
            ("attacker-target-counter-matrix", 64),
            ("missing-attacker-before-target-role", 1),
            ("missing-attacker-role", 1),
            ("missing-target-role", 1),
            ("u32-edge-status3", 4),
        ],
    );
    assert_eq!(
        BATTLE_SCRIPT_SETALWAYSHITFLAG_BRANCH_CENSUS,
        [
            ("missing-attacker-role", 2),
            ("missing-target-role", 1),
            ("set-target-packed-counter-and-owner", 68),
        ],
    );
    assert_eq!(
        BATTLE_SCRIPT_SETALWAYSHITFLAG_VECTOR_CORPUS_SHA256,
        "9a69a8a8336fd55fcbec4ad7866585239d47fe0af32f43638636fe321c9ee106",
    );
}
